import os
import sys
from datetime import datetime, timedelta

LOG_DIR = '/app/logs'
OUTPUT_CSV = '/app/summary.csv'

# reference date
ref_date = datetime(2025, 8, 12).date()

periods = ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']
severities = ['ERROR', 'WARNING', 'INFO']

# initialize counts
def init_counts():
    return {p: {s: 0 for s in severities} for p in periods}

counts = init_counts()

# define date range checks

def in_today(d):
    return d == ref_date

def in_last_7(d):
    start = ref_date - timedelta(days=6)  # include today => 7 days total
    return start <= d <= ref_date

def in_last_30(d):
    start = ref_date - timedelta(days=29)
    return start <= d <= ref_date

def in_month_to_date(d):
    start = ref_date.replace(day=1)
    return start <= d <= ref_date

# map period name to check function (excluding total)
period_checks = {
    'today': in_today,
    'last_7_days': in_last_7,
    'last_30_days': in_last_30,
    'month_to_date': in_month_to_date,
}

# iterate log files
for entry in os.scandir(LOG_DIR):
    if not entry.is_file():
        continue
    name = entry.name
    if not name.endswith('.log'):
        continue
    # expected pattern YYYY-MM-DD_<source>.log
    try:
        date_part = name.split('_')[0]
        file_date = datetime.strptime(date_part, '%Y-%m-%d').date()
    except Exception:
        # skip files not matching pattern
        continue
    # determine which periods this file contributes to
    applicable_periods = ['total']
    for period, check in period_checks.items():
        if check(file_date):
            applicable_periods.append(period)
    # read lines and count severities
    with open(entry.path, 'r', encoding='utf-8', errors='ignore') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            sev = None
            # simple check for severity word
            for s in severities:
                if s in line:
                    sev = s
                    break
            if sev is None:
                continue
            for p in applicable_periods:
                counts[p][sev] += 1

# write CSV
def write_csv(path, data):
    with open(path, 'w', newline='') as out:
        out.write('period,severity,count\n')
        order = ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']
        for period in order:
            for sev in severities:
                out.write(f"{period},{sev},{data[period][sev]}\n")

write_csv(OUTPUT_CSV, counts)
print('Summary written to', OUTPUT_CSV)

